fn main() {
    // ---- Tuples - group different types ----
    let player: (&str, i32, bool) = ("Hero", 100, true);

    // Access by index
    println!("Name: {}", player.0);
    println!("Health: {}", player.1);
    println!("Alive: {}", player.2);

    // Destructuring
    let (name, health, alive) = player;
    println!("Destructured: {} is {} HP, alive: {}", name, health, alive);

    // ---- Arrays - same type, fixed size ----
    let scores: [i32; 5] = [10, 20, 30, 40, 50];

    // Access by index
    println!("First score: {}", scores[0]);
    println!("Last score: {}", scores[4]);

    // Array length
    println!("Array length: {}", scores.len());

    // Iterating over array
    for score in scores {
        println!("Score: {}", score);
    }

    // Array literal with same value
    let zeros: [i32; 5] = [0; 5];  // [0, 0, 0, 0, 0]
    println!("Zeros: {:?}", zeros);
}

