fn main() {
    let player_stats = ("Hero", 5, 100);
    println!("Name: {}", player_stats.0);
    println!("Level: {}", player_stats.1);
    println!("Health: {}", player_stats.2);

    let high_scores = [1200, 950, 850];
    println!("Number of scores: {}", high_scores.len());
    for score in high_scores {
        println!("Score: {}", score);
    }
}
